import subprocess, os

def setup_repo(remove_readme=False, with_remote=False):
    TMP = os.popen("mktemp -d").read().strip()
    repo = os.path.join(TMP, "repo")
    os.makedirs(repo)
    open(os.path.join(repo, "README.md"), "w").write("# ideas\n")
    remote = None
    if with_remote:
        remote = os.path.join(TMP, "remote.git")
        os.system(f"git init --bare {remote} -q")
        os.system(f"cd {repo} && git init -q && git config user.email a@b.com && git config user.name test && git remote add origin {remote} && git add . && git commit -qm init && git branch -M main && git push -u origin main -q")
    else:
        os.system(f"cd {repo} && git init -q && git config user.email a@b.com && git config user.name test && git add . && git commit -qm init && git branch -M main")
    if remove_readme:
        os.remove(os.path.join(repo, "README.md"))
    home = TMP
    cfg = os.path.join(home, ".config", "eureka")
    os.makedirs(cfg, exist_ok=True)
    open(os.path.join(cfg, "config.json"), "w").write(f'{{"repo":"{repo}"}}')
    return TMP, repo, remote, home

def run_idea(home, env_extra):
    env = {"HOME":home, "PATH":"/usr/bin:/bin"}
    env.update(env_extra)
    proc = subprocess.run(["/workspace/executable"], input=b"test idea\n", stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=5, env=env)
    return proc.stdout, proc.stderr

for remove_readme in [True, False]:
    for with_remote in [True, False]:
        for editor in ["cat", "vim", "", None]:
            TMP, repo, remote, home = setup_repo(remove_readme=remove_readme, with_remote=with_remote)
            env_extra = {}
            if editor is not None:
                env_extra["EDITOR"]=editor
            else:
                # unset EDITOR, ensure not in env
                env_extra = {"PAGER":"cat"}
                # We'll run with env that excludes EDITOR
                env = {"HOME":home, "PATH":"/usr/bin:/bin", "PAGER":"cat"}
                # Remove EDITOR from env if present in os.environ
                proc = subprocess.run(["/workspace/executable"], input=b"test idea\n", stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=5, env=env)
                out, err = proc.stdout, proc.stderr
                print(f"remove_readme={remove_readme} remote={with_remote} EDITOR=None => stdout={out!r} stderr={err!r}")
                os.system(f"rm -rf {TMP}")
                continue
            out, err = run_idea(home, env_extra)
            print(f"remove_readme={remove_readme} remote={with_remote} EDITOR={editor!r} => stdout={out!r} stderr={err!r}")
            os.system(f"rm -rf {TMP}")
PY
