fn get_config_path() -> Option<PathBuf> {
    dirs::config_dir().map(|d| d.join("eureka").join("config.json"))
}

fn print_error(msg: &str) {
    eprint!(" ERROR eureka > {}", msg);
    if !msg.ends_with('\n') {
        eprintln!();
    }
