        if let Err(e) = repo.branch("main", &head_commit, false) {
            print_error(&e.to_string());
            std::process::exit(0);
        }
        // Set HEAD to main
        if let Err(e) = repo.set_head("refs/heads/main") {
            print_error(&e.to_string());
            std::process::exit(0);
        }
        // Checkout? Since main at same commit as HEAD old, checkout should be no-op, but we can force checkout to ensure?
        // For simplicity, don't extra checkout, as working tree already matches.
    }

    // Now add and commit README
    let mut index = match repo.index() {
        Ok(i) => i,
        Err(e) => {
            print_error(&e.to_string());
            std::process::exit(0);
        }
    };
    if let Err(e) = index.add_path(Path::new("README.md")) {
        print_error(&e.to_string());
        std::process::exit(0);
    }
    if let Err(e) = index.write() {
        print_error(&e.to_string());
        std::process::exit(0);
    }
    let tree_id = match index.write_tree() {
        Ok(id) => id,
        Err(e) => {
            print_error(&e.to_string());
            std::process::exit(0);
        }
    };
    let tree = match repo.find_tree(tree_id) {
        Ok(t) => t,
        Err(e) => {
            print_error(&e.to_string());
            std::process::exit(0);
        }
    };
    let sig = match repo.signature() {
        Ok(s) => s,
        Err(e) => {
            print_error(&e.to_string());
            std::process::exit(0);
        }
    };
    let parent_commit = match repo.head() {
        Ok(h) => match h.peel_to_commit() {
            Ok(c) => c,
            Err(e) => {
                print_error(&e.to_string());
