    let push_result: Result<(), git2::Error> = (|| {
        let mut remote = repo.find_remote("origin")?;
        // Push main branch
        remote.push(&["refs/heads/main"], None)?;
        Ok(())
    })();

    if let Some(ed_err) = editor_error {
        // If push succeeded, print Pushed! then editor error
        // If push failed, still print Pushed!? No, we saw when editor fails and remote present, Pushed! printed then editor error.
        // When editor fails and no remote, Pushing... printed then editor error (no Pushed! and no remote error)
        // So logic: If push_result is Ok, print Pushed! then editor error.
        // If push_result is Err, do NOT print Pushed!, just print editor error (not push error)
        // That matches observations.
        if push_result.is_ok() {
            println!("Pushed!");
            print_error(&ed_err);
        } else {
            // push failed, but editor error takes precedence, so just print editor error
            print_error(&ed_err);
        }
        std::process::exit(0);
    } else {
        // editor succeeded, handle push result
        match push_result {
            Ok(_) => {
                println!("Pushed!");
                std::process::exit(0);
            },
            Err(e) => {
                print_error(&e.to_string());
                std::process::exit(0);
            }
        }
    }
}
