fn find_in_path(bin: &str) -> Option<PathBuf> {
    let path_var = match std::env::var_os("PATH") {
        Some(p) => p,
        None => return None,
    };
    let path_str = path_var.to_string_lossy();
    if path_str.is_empty() {
        return None;
    }
    for dir in path_str.split(':') {
        if dir.is_empty() {
            continue;
        }
        let full = Path::new(dir).join(bin);
        if let Ok(meta) = std::fs::metadata(&full) {
            if meta.is_file() {
                return Some(full);
            }
        }
    }
    None
}

fn build_cli() -> Command {
    Command::new("eureka")
        .bin_name("executable")
        .about("Input and store your ideas without leaving the terminal")
        .version("2.0.0")
        .arg(Arg::new("clear-config").long("clear-config").help("Clear your stored configuration").action(clap::ArgAction::SetTrue))
        .arg(Arg::new("view").short('v').long("view").help("View ideas with your $PAGER env variable. If unset use less").action(clap::ArgAction::SetTrue))
}

fn format_git_error(e: git2::Error) -> String {
    let msg = e.to_string();
    // The original for "could not find repository at" vs "from" differs:
    // Our version says "at" but original says "from"
    // Let's replace "at '" with "from '" for that specific pattern to match original?
    // The error message comes from libgit2, version may differ in wording between libgit2 versions.
    // We observed: our libgit2 says "could not find repository at '/path'" but original says "could not find repository from '/path'"
    // So we need to replace " at '" with " from '" for this specific case to match.
    if msg.contains("could not find repository at") {
        msg.replace("could not find repository at", "could not find repository from")
    } else {
        msg
    }
}

fn main() {
    let matches = build_cli().get_matches();

    let clear_config = matches.get_flag("clear-config");
    let view = matches.get_flag("view");

    if clear_config {
        if let Some(cfg_path) = get_config_path() {
            match std::fs::remove_file(&cfg_path) {
                Ok(_) => std::process::exit(0),
                Err(e) => {
                    print_error(&e.to_string());
                    std::process::exit(0);
                }
            }
        } else {
            print_error("No such file or directory (os error 2)");
            std::process::exit(0);
        }
    }

    if view {
        let cfg_path = match get_config_path() {
            Some(p) => p,
            None => {
                print_error("No such file or directory (os error 2)");
                std::process::exit(0);
            }
        };
        let cfg_content = match std::fs::read_to_string(&cfg_path) {
            Ok(c) => c,
            Err(e) => {
                print_error(&e.to_string());
                std::process::exit(0);
            }
        };
        let cfg: Config = match serde_json::from_str(&cfg_content) {
            Ok(c) => c,
            Err(e) => {
                print_error(&e.to_string());
                std::process::exit(0);
            }
        };
        let repo_path = PathBuf::from(cfg.repo);
        let readme_path = repo_path.join("README.md");

        let pager_opt = std::env::var("PAGER").ok();

        if let Some(pager_val) = pager_opt {
            match std::fs::metadata(&readme_path) {
                Ok(_) => {},
                Err(e) => {
                    print_error(&e.to_string());
                    std::process::exit(0);
                }
            }
            let mut cmd = ProcCommand::new(&pager_val);
            cmd.arg(&readme_path);
            cmd.stdin(Stdio::inherit());
            match cmd.status() {
                Ok(status) => std::process::exit(status.code().unwrap_or(0)),
                Err(e) => {
                    print_error(&e.to_string());
                    std::process::exit(0);
                }
            }
        } else {
            let less_path = find_in_path("less");
            if less_path.is_none() {
                print_error("cannot find binary path");
                std::process::exit(0);
            }
            match std::fs::metadata(&readme_path) {
                Ok(_) => {},
                Err(e) => {
                    print_error(&e.to_string());
                    std::process::exit(0);
                }
            }
            let mut cmd = ProcCommand::new("less");
            cmd.arg(&readme_path);
            cmd.stdin(Stdio::inherit());
            match cmd.status() {
                Ok(status) => std::process::exit(status.code().unwrap_or(0)),
                Err(e) => {
                    print_error(&e.to_string());
                    std::process::exit(0);
                }
            }
        }
    }

    let cfg_path_opt = get_config_path();
    let cfg_path = match cfg_path_opt {
        Some(p) => p,
        None => {
            print_error("No such file or directory (os error 2)");
            std::process::exit(0);
        }
    };

    if !cfg_path.exists() {
        let banner = "############################################################\n####                  First Time Setup                  ####\n############################################################\n\nThis tool requires you to have a repository with a README.md\nin the root folder. The markdown file is where your ideas\nwill be stored.\n\nOnce first time setup has completed, simply run Eureka again\nto begin writing down ideas.\n        \n";
        print!("\x1b[0m\x1b[33m{}", banner);
        print!("\x1b[0m\x1b[0m\x1b[1m\x1b[32mAbsolute path to your idea repo\n\x1b[0m> ");
        io::stdout().flush().unwrap();

        let stdin = io::stdin();
        let mut input = String::new();
        loop {
            input.clear();
            let bytes = stdin.read_line(&mut input).unwrap();
            if bytes == 0 {
                print!("\x1b[0m\x1b[1m\x1b[32mAbsolute path to your idea repo\n\x1b[0m> ");
                io::stdout().flush().unwrap();
                continue;
            }
            let trimmed = input.trim();
            if trimmed.is_empty() {
                print!("\x1b[0m\x1b[1m\x1b[32mAbsolute path to your idea repo\n\x1b[0m> ");
                io::stdout().flush().unwrap();
                continue;
            }
            let path = Path::new(trimmed);
            if !path.is_absolute() {
                // Original prints Path must be absolute with two resets before green? Actually error red
                // After error, it prints again Absolute path prompt
                print!("\x1b[0m\x1b[31mPath must be absolute\n\x1b[0m");
                print!("\x1b[0m\x1b[1m\x1b[32mAbsolute path to your idea repo\n\x1b[0m> ");
                io::stdout().flush().unwrap();
                continue;
            }
            if let Some(parent) = cfg_path.parent() {
                let _ = std::fs::create_dir_all(parent);
            }
            let cfg = Config { repo: trimmed.to_string() };
            let json = serde_json::to_string(&cfg).unwrap();
            let _ = std::fs::write(&cfg_path, json);
            println!("First time setup complete. Happy ideation!");
            std::process::exit(0);
        }
    }

    let cfg_content = match std::fs::read_to_string(&cfg_path) {
        Ok(c) => c,
        Err(e) => {
            print_error(&e.to_string());
            std::process::exit(0);
        }
    };
    let cfg: Config = match serde_json::from_str(&cfg_content) {
        Ok(c) => c,
        Err(e) => {
            print_error(&e.to_string());
            std::process::exit(0);
        }
    };
    let repo_path = PathBuf::from(cfg.repo.trim());
    let readme_path = repo_path.join("README.md");

    let mut summary = String::new();
    loop {
        print!("\x1b[0m\x1b[1m\x1b[32m>> Idea summary\n\x1b[0m> ");
        io::stdout().flush().unwrap();
        let mut input = String::new();
        let bytes = io::stdin().read_line(&mut input).unwrap();
        if bytes == 0 {
            continue;
        }
        let trimmed = input.trim();
        if trimmed.is_empty() {
            continue;
        }
        summary = trimmed.to_string();
        break;
    }

    let repo = match git2::Repository::open(&repo_path) {
        Ok(r) => r,
        Err(e) => {
            print_error(&format_git_error(e));
            std::process::exit(0);
        }
    };

    let readme_exists = readme_path.exists();

    let editor_opt = std::env::var("EDITOR").ok();
    let mut editor_error: Option<String> = None;

    if readme_exists {
        if let Some(ed_val) = editor_opt {
            let mut cmd = ProcCommand::new(&ed_val);
            cmd.arg(&readme_path);
            cmd.stdin(Stdio::inherit());
            cmd.stdout(Stdio::inherit());
            cmd.stderr(Stdio::inherit());
            match cmd.status() {
                Ok(_) => {},
                Err(e) => {
                    editor_error = Some(e.to_string());
                }
            }
        } else {
            if let Some(vi_path) = find_in_path("vi") {
                let mut cmd = ProcCommand::new(vi_path);
                cmd.arg(&readme_path);
                cmd.stdin(Stdio::inherit());
                cmd.stdout(Stdio::inherit());
                cmd.stderr(Stdio::inherit());
                match cmd.status() {
                    Ok(_) => {},
                    Err(e) => {
                        editor_error = Some(e.to_string());
                    }
                }
            } else {
                editor_error = Some("cannot find binary path".to_string());
            }
        }
    }

    println!("Adding and committing your new idea to main..");

    if !readme_exists {
        print_error("No such file or directory (os error 2)");
        std::process::exit(0);
    }

    let main_exists = repo.find_branch("main", git2::BranchType::Local).is_ok();
    if main_exists {
        let current_branch_name: Option<String> = match repo.head() {
            Ok(head) => {
                if head.is_branch() {
                    match head.shorthand() {
                        Ok(s) => Some(s.to_string()),
                        Err(_) => None,
                    }
                } else {
                    None
                }
            },
            Err(_) => None,
        };
        if current_branch_name.as_deref() != Some("main") {
            if let Ok(main_ref) = repo.find_reference("refs/heads/main") {
                if let Ok(main_commit) = main_ref.peel_to_commit() {
                    let mut cb = git2::build::CheckoutBuilder::new();
                    match repo.checkout_tree(main_commit.as_object(), Some(&mut cb)) {
                        Ok(_) => {
                            let _ = repo.set_head("refs/heads/main");
                        },
                        Err(e) => {
                            print_error(&format_git_error(e));
                            std::process::exit(0);
                        }
                    }
                }
            }
        }
    } else {
        let head_commit = match repo.head() {
            Ok(h) => match h.peel_to_commit() {
                Ok(c) => c,
                Err(e) => {
                    print_error(&format_git_error(e));
                    std::process::exit(0);
                }
            },
            Err(e) => {
                print_error(&format_git_error(e));
                std::process::exit(0);
            }
        };
        if let Err(e) = repo.branch("main", &head_commit, false) {
            print_error(&format_git_error(e));
            std::process::exit(0);
        }
        if let Err(e) = repo.set_head("refs/heads/main") {
            print_error(&format_git_error(e));
            std::process::exit(0);
        }
    }

    let mut index = match repo.index() {
        Ok(i) => i,
        Err(e) => {
            print_error(&format_git_error(e));
            std::process::exit(0);
        }
    };
    if let Err(e) = index.add_path(Path::new("README.md")) {
        print_error(&format_git_error(e));
        std::process::exit(0);
    }
    if let Err(e) = index.write() {
        print_error(&format_git_error(e));
        std::process::exit(0);
    }
    let tree_id = match index.write_tree() {
        Ok(id) => id,
        Err(e) => {
            print_error(&format_git_error(e));
            std::process::exit(0);
        }
    };
    let tree = match repo.find_tree(tree_id) {
        Ok(t) => t,
        Err(e) => {
            print_error(&format_git_error(e));
            std::process::exit(0);
        }
    };
    let sig = match repo.signature() {
        Ok(s) => s,
        Err(e) => {
            print_error(&format_git_error(e));
            std::process::exit(0);
        }
    };
    let parent_commit = match repo.head() {
        Ok(h) => match h.peel_to_commit() {
            Ok(c) => c,
            Err(e) => {
                print_error(&format_git_error(e));
                std::process::exit(0);
            }
        },
        Err(e) => {
            print_error(&format_git_error(e));
            std::process::exit(0);
        }
    };

    match repo.commit(Some("HEAD"), &sig, &sig, &summary, &tree, &[&parent_commit]) {
        Ok(_) => {},
        Err(e) => {
            print_error(&format_git_error(e));
            std::process::exit(0);
        }
    };

    println!("Added and committed!");
    println!("Pushing your new idea..");

    let push_result: Result<(), git2::Error> = (|| {
        let mut remote = repo.find_remote("origin")?;
        remote.push(&["refs/heads/main"], None)?;
        Ok(())
    })();

    if let Some(ed_err) = editor_error {
        if push_result.is_ok() {
            println!("Pushed!");
            print_error(&ed_err);
        } else {
            print_error(&ed_err);
        }
        std::process::exit(0);
    } else {
        match push_result {
            Ok(_) => {
                println!("Pushed!");
                std::process::exit(0);
            },
            Err(e) => {
                print_error(&format_git_error(e));
                std::process::exit(0);
            }
        }
    }
}
