import subprocess, os

def run_new(home, args, env_extra, input_bytes):
    env = {"HOME":home, "PATH":"/usr/bin:/bin"}
    env.update(env_extra)
    proc = subprocess.run(["/workspace/target/debug/eureka"]+args, input=input_bytes, stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=5, env=env)
    return proc.stdout, proc.stderr

def run_orig(home, args, env_extra, input_bytes):
    env = {"HOME":home, "PATH":"/usr/bin:/bin"}
    env.update(env_extra)
    proc = subprocess.run(["/workspace/executable"]+args, input=input_bytes, stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=5, env=env)
    return proc.stdout, proc.stderr

def test(label, setup_fn, args, env_extra, input_bytes):
    TMP_new = os.popen("mktemp -d").read().strip()
    TMP_orig = os.popen("mktemp -d").read().strip()
    setup_fn(TMP_new)
    setup_fn(TMP_orig)
    out_new, err_new = run_new(TMP_new, args, env_extra, input_bytes)
    out_orig, err_orig = run_orig(TMP_orig, args, env_extra, input_bytes)
    ok = (out_new==out_orig and err_new==err_orig)
    print(f"{label}: {'OK' if ok else 'DIFF'}")
    if not ok:
        print("NEW stdout:", out_new)
        print("ORIG stdout:", out_orig)
        print("NEW stderr:", err_new)
        print("ORIG stderr:", err_orig)
    os.system(f"rm -rf {TMP_new} {TMP_orig}")

